def collapse(values):
    """Collapse an iterable of integers into comma-joined ranges.

    Consecutive integers are rendered as "start-end"; isolated values are
    rendered bare. Duplicates are removed and the result is ascending.
    Negative runs render literally (e.g. "-3--1"). Raises TypeError for
    booleans or non-integers. The input is never mutated.
    """
    items = list(values)

    for item in items:
        if isinstance(item, bool) or not isinstance(item, int):
            raise TypeError(
                "collapse() expects integers, got {!r}".format(type(item).__name__)
            )

    unique = sorted(set(items))
    if not unique:
        return ""

    parts = []
    start = previous = unique[0]
    for value in unique[1:]:
        if value == previous + 1:
            previous = value
        else:
            parts.append(str(start) if start == previous else "{}-{}".format(start, previous))
            start = previous = value
    parts.append(str(start) if start == previous else "{}-{}".format(start, previous))

    return ",".join(parts)

