import heapq


class DependencyError(ValueError):
    pass


def _is_string_like(value):
    """True for str/bytes-like objects that must not be used as dependency iterables."""
    return isinstance(value, (str, bytes, bytearray))


def build_order(dependencies):
    """Return a deterministic topological order of ``dependencies``.

    ``dependencies`` maps each task name to an iterable of names that task
    depends on. The returned order always picks the lexically smallest task
    whose dependencies have already been satisfied.

    Raises :class:`DependencyError` for empty/non-string names, string-like
    dependency iterables, self-dependencies, unknown dependencies, and cycles.
    The input is never mutated; duplicate dependency entries are ignored.
    """
    if dependencies is None:
        raise DependencyError("dependencies must be a mapping of task names to dependency iterables")

    try:
        items = list(dependencies.items())
    except AttributeError:
        raise DependencyError(
            "dependencies must be a mapping of task names to dependency iterables"
        ) from None

    # First pass: validate task names and collect the set of known tasks.
    known = set()
    tasks = []
    for name, deps in items:
        if not isinstance(name, str) or not name:
            raise DependencyError(
                "task names must be non-empty strings, got {!r}".format(name)
            )
        if name in known:
            # Defensive: a mapping cannot contain duplicate keys, but guard
            # anyway so the structure stays consistent.
            raise DependencyError("duplicate task name: {!r}".format(name))
        known.add(name)
        tasks.append((name, deps))

    in_degree = {name: 0 for name in known}
    dependents = {name: [] for name in known}

    # Second pass: validate and normalize each dependency list.
    for name, deps in tasks:
        if deps is None:
            raise DependencyError(
                "dependencies of task {!r} must be an iterable of names, got None".format(name)
            )
        if _is_string_like(deps):
            raise DependencyError(
                "dependencies of task {!r} must be an iterable of names, not a string".format(name)
            )
        try:
            iterator = iter(deps)
        except TypeError:
            raise DependencyError(
                "dependencies of task {!r} must be an iterable of names".format(name)
            ) from None

        seen = set()
        for dep in iterator:
            if not isinstance(dep, str) or not dep:
                raise DependencyError(
                    "dependency names must be non-empty strings, got {!r}".format(dep)
                )
            if dep == name:
                raise DependencyError("task {!r} cannot depend on itself".format(name))
            if dep not in known:
                raise DependencyError(
                    "task {!r} depends on unknown task {!r}".format(name, dep)
                )
            if dep in seen:
                # Duplicate entries add no additional effect.
                continue
            seen.add(dep)
            in_degree[name] += 1
            dependents[dep].append(name)

    # Kahn's algorithm with a heap so ties are broken lexically.
    available = [name for name, degree in in_degree.items() if degree == 0]
    heapq.heapify(available)
    order = []
    while available:
        current = heapq.heappop(available)
        order.append(current)
        for dependent in dependents[current]:
            in_degree[dependent] -= 1
            if in_degree[dependent] == 0:
                heapq.heappush(available, dependent)

    if len(order) != len(known):
        remaining = sorted(name for name, degree in in_degree.items() if degree > 0)
        raise DependencyError(
            "dependency cycle detected involving: {}".format(", ".join(repr(n) for n in remaining))
        )

    return order

