import ntpath
from pathlib import Path


class UnsafePathError(ValueError):
    pass


def build_extraction_plan(names, destination: Path):
    """Return a filesystem-free plan for extracting file members.

    Member names are interpreted using archive-style, platform-independent
    rules: both kinds of slash are separators, while the returned paths use
    the semantics of :class:`pathlib.Path` on the current platform.
    """
    destination = Path(destination)
    plan = []

    # These component tuples are case-folded.  ``required_directories`` also
    # lets us reject a file whose path would have to be a directory for a
    # different planned file (for example, "a" together with "a/b").
    file_targets = set()
    required_directories = set()

    for original_name in names:
        if not isinstance(original_name, str) or not original_name:
            raise UnsafePathError("archive member name must be a non-empty string")
        if "\x00" in original_name:
            raise UnsafePathError("archive member name contains a NUL byte")
        if original_name[0] in "/\\":
            raise UnsafePathError("absolute and UNC member paths are not allowed")
        if original_name[-1] in "/\\":
            raise UnsafePathError("directory entries are not allowed")

        # splitdrive is from ntpath deliberately: drive paths must be rejected
        # even when this code is running on a non-Windows host.
        if ntpath.splitdrive(original_name)[0]:
            raise UnsafePathError("drive-qualified member paths are not allowed")

        components = []
        for component in original_name.replace("\\", "/").split("/"):
            if not component or component == ".":
                continue
            if component == "..":
                raise UnsafePathError("parent path components are not allowed")
            components.append(component)

        if not components:
            # Names made solely from dots and separators denote directories,
            # not files, even if they did not have a trailing separator.
            raise UnsafePathError("member path does not name a file")

        normalized_name = "/".join(components)
        if ntpath.splitdrive(normalized_name)[0]:
            raise UnsafePathError("drive-qualified member paths are not allowed")

        target = destination.joinpath(*components)
        try:
            relative = target.relative_to(destination)
        except ValueError as exc:
            raise UnsafePathError("member target escapes the destination") from exc
        if relative == Path("."):
            raise UnsafePathError("member path does not name a file")

        key = tuple(component.casefold() for component in components)
        prefixes = {key[:index] for index in range(1, len(key))}
        if key in file_targets or key in required_directories:
            raise UnsafePathError("archive members have colliding targets")
        if prefixes & file_targets:
            raise UnsafePathError("a file target conflicts with another member")

        file_targets.add(key)
        required_directories.update(prefixes)
        plan.append((original_name, target))

    return plan

