from collections.abc import Mapping
from decimal import Decimal, DecimalException
from fractions import Fraction


def allocate(total_cents, weights):
    """Allocate *total_cents* proportionally using largest remainders.

    Weight conversion is performed by :class:`Decimal`, and all subsequent
    calculations use exact integer/rational arithmetic.
    """
    if isinstance(total_cents, bool) or not isinstance(total_cents, int):
        raise TypeError("total_cents must be an integer")
    if total_cents < 0:
        raise ValueError("total_cents must be non-negative")
    if not isinstance(weights, Mapping):
        raise TypeError("weights must be a mapping")
    if not weights:
        raise TypeError("weights must not be empty")

    converted = {}
    for key, value in weights.items():
        if not isinstance(key, str) or not key:
            raise TypeError("weight keys must be non-empty strings")
        try:
            weight = Decimal(value)
        except TypeError:
            raise TypeError("weight values must be accepted by Decimal") from None
        except (DecimalException, ValueError):
            raise ValueError("weight values must be valid numbers") from None

        if not weight.is_finite():
            raise ValueError("weights must be finite")
        if weight < 0:
            raise ValueError("weights must be non-negative")
        converted[key] = Fraction(weight)

    total_weight = sum(converted.values(), Fraction(0))
    if total_weight <= 0:
        raise ValueError("at least one weight must be positive")

    keys = sorted(converted)
    result = {}
    remainders = []
    allocated = 0
    for key in keys:
        exact_share = total_cents * converted[key] / total_weight
        floor_share = exact_share.numerator // exact_share.denominator
        result[key] = floor_share
        allocated += floor_share
        remainders.append((exact_share - floor_share, key))

    # Sorting is stable and keys are already lexical, so equal remainders keep
    # lexical order.  At most len(weights) - 1 cents remain after flooring.
    remainders.sort(key=lambda item: item[0], reverse=True)
    for _, key in remainders[: total_cents - allocated]:
        result[key] += 1

    return result

