import heapq


class DependencyError(ValueError):
    pass


def build_order(dependencies):
    """Return a deterministic topological ordering of *dependencies*.

    Each mapping key is a task and its value is an iterable containing the
    tasks that must precede it.  When more than one task is ready, the
    lexicographically smallest one is selected.
    """
    if not isinstance(dependencies, Mapping):
        raise DependencyError("dependencies must be a mapping")

    # Snapshot the keys up front so that validation and graph construction do
    # not alter the caller's mapping or any dependency collections.
    task_names = list(dependencies.keys())
    for name in task_names:
        if not isinstance(name, str) or not name:
            raise DependencyError("task names must be non-empty strings")

    tasks = set(task_names)
    prerequisites = {}

    for task in task_names:
        entries = dependencies[task]
        if isinstance(entries, (str, bytes, bytearray, memoryview)):
            raise DependencyError("dependencies for a task must not be string-like")

        try:
            entries = iter(entries)
        except TypeError as exc:
            raise DependencyError("dependencies for a task must be iterable") from exc

        unique = set()
        for dependency in entries:
            if not isinstance(dependency, str) or not dependency:
                raise DependencyError("dependency names must be non-empty strings")
            if dependency == task:
                raise DependencyError("a task cannot depend on itself")
            if dependency not in tasks:
                raise DependencyError("dependency refers to a missing task")
            unique.add(dependency)
        prerequisites[task] = unique

    dependents = {task: [] for task in task_names}
    indegree = {}
    for task, required in prerequisites.items():
        indegree[task] = len(required)
        for dependency in required:
            dependents[dependency].append(task)

    available = [task for task in task_names if indegree[task] == 0]
    heapq.heapify(available)
    order = []

    while available:
        task = heapq.heappop(available)
        order.append(task)
        for dependent in dependents[task]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(available, dependent)

    if len(order) != len(task_names):
        raise DependencyError("dependency graph contains a cycle")

    return order

