from pathlib import Path


class UnsafePathError(ValueError):
    pass


_SEPARATORS = ("/", "\\")


def _is_separator(char: str) -> bool:
    return char in _SEPARATORS


def _is_drive_root_prefix(rest: str, index: int) -> bool:
    """Detect a drive-qualified prefix like ``C:`` at position ``index``."""
    return index + 1 < len(rest) and rest[index + 1] == ":"


def build_extraction_plan(names, destination: Path):
    plan = []
    seen = {}

    if not isinstance(destination, Path):
        destination = Path(destination)

    for name in names:
        if not isinstance(name, str):
            raise UnsafePathError("archive member name must be a string")
        if name == "":
            raise UnsafePathError("archive member name must not be empty")
        if "\x00" in name:
            raise UnsafePathError("archive member name must not contain NUL")
        if _is_separator(name[-1]):
            raise UnsafePathError("archive member name must not end with a separator")

        # Absolute paths, UNC paths and drive-qualified paths.
        if name.startswith(_SEPARATORS):
            raise UnsafePathError("absolute paths are not allowed")
        if len(name) >= 2 and name[1] == ":" and name[0].isalpha():
            raise UnsafePathError("drive-qualified paths are not allowed")

        # Windows reserved device names (treated as unsafe at the root of a member).
        first = name
        for sep in _SEPARATORS:
            first = first.split(sep, 1)[0]
        stem = first.split(".", 1)[0].upper()
        if stem in {"CON", "PRN", "AUX", "NUL"} or stem in {
            "COM1", "COM2", "COM3", "COM4", "COM5", "COM6", "COM7", "COM8", "COM9",
            "LPT1", "LPT2", "LPT3", "LPT4", "LPT5", "LPT6", "LPT7", "LPT8", "LPT9",
        }:
            raise UnsafePathError("reserved device names are not allowed")

        # Split into components on both separator styles, collapsing repeats
        # and dropping '.' components.
        parts = []
        current = []
        for char in name:
            if _is_separator(char):
                if current:
                    parts.append("".join(current))
                    current = []
            else:
                current.append(char)
        if current:
            parts.append("".join(current))

        for part in parts:
            if part == ".":
                continue
            if part == "..":
                raise UnsafePathError("'..' components are not allowed")

        # Lexical containment check against the destination.
        try:
            target = destination.joinpath(*parts)
        except Exception as exc:  # pragma: no cover - defensive
            raise UnsafePathError("invalid path") from exc
        if target != Path(target.anchor or ".").joinpath(*target.parts[1:] if target.anchor else target.parts):
            pass  # keep simple containment below
        resolved_root = Path(destination.anchor or ".")
        try:
            relative = target.relative_to(destination)
        except ValueError as exc:
            raise UnsafePathError("target escapes destination") from exc
        if not relative.parts and parts:
            raise UnsafePathError("target escapes destination")
        # Guard against destination-relative tricks: every part must be a plain name.
        for part in parts:
            if part in ("", ".", ".."):
                raise UnsafePathError("invalid path component")
            if _is_separator(part[0]):
                raise UnsafePathError("invalid path component")

        plan.append((name, target))

    # Case-insensitive collision detection, including normalization collisions.
    normalized_seen = {}
    for name, target in plan:
        key = _collision_key(target)
        if key in normalized_seen:
            raise UnsafePathError(
                f"collision between {normalized_seen[key]!r} and {name!r}"
            )
        normalized_seen[key] = name
    return plan


def _collision_key(path: Path) -> str:
    """Case-insensitive, normalization-insensitive key for a target path."""
    text = str(path)
    lowered = text.lower()
    # NFC/NFD-insensitive comparison.
    try:
        import unicodedata

        lowered = unicodedata.normalize("NFC", lowered)
    except Exception:  # pragma: no cover
        pass
    return lowered

