import heapq


class DependencyError(ValueError):
    pass


def build_order(dependencies):
    """Return a deterministic topological order of tasks.

    dependencies: mapping from task name (str) to an iterable of task names
    that task depends on. Every dependency must itself be a key of the
    mapping. Ties are broken by always choosing the lexically smallest
    currently available task. Raises DependencyError for invalid input or
    cyclic dependencies. The input is not mutated.
    """
    if not hasattr(dependencies, "items"):
        raise DependencyError("dependencies must be a mapping")

    try:
        items = list(dependencies.items())
    except Exception:
        raise DependencyError("dependencies must be a mapping")

    graph = {}
    for task, deps in items:
        if not isinstance(task, str) or not task:
            raise DependencyError("task names must be non-empty strings")
        if isinstance(deps, (str, bytes, bytearray)):
            raise DependencyError(
                "dependencies must be an iterable of task names, not a string")
        try:
            dep_list = list(deps)
        except TypeError:
            raise DependencyError(
                "dependencies must be an iterable of task names")
        graph[task] = dep_list

    for task, dep_list in graph.items():
        for dep in dep_list:
            if not isinstance(dep, str) or not dep:
                raise DependencyError(
                    "dependency names must be non-empty strings")
            if dep not in graph:
                raise DependencyError(
                    "unknown task in dependencies: {!r}".format(dep))

    remaining_deps = {}
    dependents = {task: set() for task in graph}
    for task, dep_list in graph.items():
        unique_deps = set(dep_list)
        if task in unique_deps:
            raise DependencyError(
                "task cannot depend on itself: {!r}".format(task))
        remaining_deps[task] = len(unique_deps)
        for dep in unique_deps:
            dependents[dep].add(task)

    available = [
        task for task, count in remaining_deps.items() if count == 0]
    heapq.heapify(available)

    order = []
    while available:
        task = heapq.heappop(available)
        order.append(task)
        for dependent in dependents[task]:
            remaining_deps[dependent] -= 1
            if remaining_deps[dependent] == 0:
                heapq.heappush(available, dependent)

    if len(order) != len(graph):
        unresolved = sorted(set(graph) - set(order))
        raise DependencyError(
            "cyclic dependency involving: {}".format(
                ", ".join(repr(t) for t in unresolved)))

    return order

