def collapse(values):
    """Collapse an iterable of integers into a comma-joined range string.

    Accepts any iterable of integers. Duplicates are removed, values are
    sorted ascending, and consecutive runs are rendered as "start-end"
    while isolated values stay bare (e.g. "-3--1,1-2,4"). Returns "" for
    empty input. Raises TypeError for booleans or non-integers. The input
    is never mutated.
    """
    try:
        items = list(values)
    except TypeError:
        raise TypeError("collapse() expects an iterable of integers")

    for item in items:
        if isinstance(item, bool) or not isinstance(item, int):
            raise TypeError(
                "collapse() expects only integers, got %s" % type(item).__name__
            )

    unique = sorted(set(items))
    if not unique:
        return ""

    def render(start, end):
        if start == end:
            return str(start)
        return "%d-%d" % (start, end)

    parts = []
    run_start = prev = unique[0]
    for value in unique[1:]:
        if value == prev + 1:
            prev = value
        else:
            parts.append(render(run_start, prev))
            run_start = prev = value
    parts.append(render(run_start, prev))

    return ",".join(parts)

