class DependencyError(ValueError):
    pass


def build_order(dependencies):
    """Return a deterministic topological order of tasks.

    dependencies: mapping from task name (str) to an iterable of task
    names that task depends on.

    Uses Kahn's algorithm, always picking the lexically smallest
    currently available task.
    """
    if not isinstance(dependencies, dict):
        # Allow any mapping? Requirement says "mapping", be permissive
        # only for real mappings; a plain dict is the normal case.
        try:
            items = list(dependencies.items())
        except AttributeError:
            raise DependencyError("dependencies must be a mapping")
    else:
        items = list(dependencies.items())

    graph = {}
    for name, deps in items:
        if not isinstance(name, str) or not name:
            raise DependencyError("task names must be non-empty strings")
        if deps is None:
            raise DependencyError(
                "dependencies for %r must be an iterable of names" % name)
        if isinstance(deps, (str, bytes, bytearray)):
            raise DependencyError(
                "dependencies for %r must be an iterable of names, "
                "not a string" % name)
        try:
            dep_list = list(deps)
        except TypeError:
            raise DependencyError(
                "dependencies for %r must be an iterable of names" % name)
        seen = set()
        unique_deps = []
        for dep in dep_list:
            if not isinstance(dep, str) or not dep:
                raise DependencyError(
                    "dependency names must be non-empty strings")
            if dep == name:
                raise DependencyError(
                    "task %r cannot depend on itself" % name)
            if dep not in seen:
                seen.add(dep)
                unique_deps.append(dep)
        graph[name] = unique_deps

    for name, unique_deps in graph.items():
        for dep in unique_deps:
            if dep not in graph:
                raise DependencyError(
                    "task %r depends on unknown task %r" % (name, dep))

    remaining = {name: set(deps) for name, deps in graph.items()}
    order = []
    while remaining:
        available = sorted(
            name for name, deps in remaining.items() if not deps)
        if not available:
            raise DependencyError("dependency cycle detected")
        current = available[0]
        order.append(current)
        del remaining[current]
        for deps in remaining.values():
            deps.discard(current)

    return order
